<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='shortlist_view';$pageTitle='Shortlist Details';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$sid=(int)($_GET['id']??0);$s=$conn->prepare("SELECT * FROM recruiter_shortlists WHERE id=? AND recruiter_id=?");$s->bind_param('ii',$sid,$uid);$s->execute();$sl=$s->get_result()->fetch_assoc();$s->close();if(!$sl){http_response_code(403);exit('Shortlist not found or access denied.');}$rows=[];$s=$conn->prepare("SELECT rsc.added_at,cp.user_id,cp.headline,cp.city,cp.province,cp.verification_status,u.first_name,u.last_name,u.email,cc.status consent_status,cc.expires_at FROM recruiter_shortlist_candidates rsc JOIN candidate_profiles cp ON cp.user_id=rsc.candidate_id JOIN users u ON u.id=cp.user_id LEFT JOIN candidate_consents cc ON cc.candidate_id=cp.user_id AND cc.consent_type='recruiter_discovery' WHERE rsc.shortlist_id=? ORDER BY rsc.added_at DESC");$s->bind_param('i',$sid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();$criteria=json_decode((string)$sl['search_criteria_json'],true);if(!is_array($criteria))$criteria=[];require __DIR__.'/_layout_start.php';?>
<div class="rc-detail-hero"><span class="rc-eyebrow">Client Shortlist</span><h2><?=e($sl['name'])?></h2><p><?=e((string)($sl['client_name']?:'No client specified'))?></p><div class="rc-chips"><b>Taxonomy <?=e($sl['taxonomy_version'])?></b><b><?=number_format(count($rows))?> candidates</b></div></div>
<div class="rc-grid-2"><section class="rc-card"><div class="rc-card__header"><h3>Stored Search Criteria</h3></div><div class="rc-card__body rc-details"><?php foreach($criteria as $k=>$v):?><div><span><?=e(rc_label($k))?></span><strong><?=e((string)($v!==''?$v:'Any'))?></strong></div><?php endforeach;?></div></section><section class="rc-card"><div class="rc-card__header"><h3>Reproducibility</h3></div><div class="rc-card__body rc-trust"><div><i class="fas fa-code-branch"></i><div><strong>Taxonomy Version</strong><span><?=e($sl['taxonomy_version'])?></span></div></div><div><i class="fas fa-calendar"></i><div><strong>Created</strong><span><?=e(rc_datetime($sl['created_at']))?></span></div></div></div></section></div>
<section class="rc-card"><div class="rc-card__header"><h3>Shortlisted Candidates</h3></div><div class="rc-table-wrap"><table class="rc-table"><thead><tr><th>Candidate</th><th>Location</th><th>Verification</th><th>Consent</th><th>Added</th><th></th></tr></thead><tbody><?php foreach($rows as $x):$f=trim((string)$x['first_name']);$l=trim((string)$x['last_name']);$valid=($x['consent_status']??'')==='consented'&&(empty($x['expires_at'])||strtotime($x['expires_at'])>time());?><tr><td><strong><?=e(trim($f.' '.$l)?:'Candidate')?></strong><span><?=e((string)($x['headline']?:$x['email']))?></span></td><td><?=e(trim((string)$x['city'].', '.(string)$x['province'],' ,'))?></td><td><?=e(rc_label($x['verification_status']))?></td><td><span class="rc-status rc-status--<?=$valid?'success':'danger'?>"><?=$valid?'Valid':'Unavailable'?></span></td><td><?=e(rc_date($x['added_at']))?></td><td><?php if($valid):?><a class="rc-icon-btn" href="<?=url('recruiter/candidate_view.php?id='.$x['user_id'])?>"><i class="fas fa-arrow-right"></i></a><?php else:?><span class="rc-icon-btn"><i class="fas fa-lock"></i></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/_layout_end.php';?>